from typing import Dict, TypedDict
import uuid
from datetime import datetime
from typing import Optional, Dict



class ParticipantInfo(TypedDict):
    participant_id: str
    name: str
    date_of_birth: str
    contact_info: str
    consent_status: str

class ClinicalTrialInfo(TypedDict):
    trial_id: str
    name: str
    description: str
    phase: str
    status: str
    start_date: str
    end_date: str

class EnrollmentInfo(TypedDict):
    enrollment_id: str
    participant_id: str
    trial_id: str
    enrollment_date: str
    enrollment_status: str

class UserAccountInfo(TypedDict):
    account_id: str
    participant_id: str
    username: str
    hashed_password: str
    account_status: str

class ClinicalTrialParticipantManagementSystem:
    def __init__(self, init_config: dict):
        """
        Clinical Trial Participant Management System environment.

        Entities:
        - participants: Dict[participant_id, ParticipantInfo]
        - clinical_trials: Dict[trial_id, ClinicalTrialInfo]
        - enrollments: Dict[enrollment_id, EnrollmentInfo]
        - user_accounts: Dict[account_id, UserAccountInfo]

        Constraints:
        - Only participants with valid consent_status may be enrolled in trials.
        - Each enrollment must reference valid participant and clinical trial records.
        - Enrollment_status must use predefined values (e.g., "enrolled", "withdrawn", "completed").
        - User access scope is limited: A user can only view their own enrollments.
        """

        # Participant records
        self.participants: Dict[str, ParticipantInfo] = {}

        # Clinical trial records
        self.clinical_trials: Dict[str, ClinicalTrialInfo] = {}

        # Enrollment records
        self.enrollments: Dict[str, EnrollmentInfo] = {}

        # User account records
        self.user_accounts: Dict[str, UserAccountInfo] = {}

        self.init_config = init_config

    def get_user_account_by_username(self, username: str) -> dict:
        """
        Retrieve a user account's information by username.

        Args:
            username (str): The unique username to search for.

        Returns:
            dict: {
                "success": True,
                "data": UserAccountInfo,  # User account info dict
            }
            or
            {
                "success": False,
                "error": str  # Reason not found
            }

        Constraints:
            - If multiple accounts share the same username (should not happen), returns the first match found.
            - Returns error if username not found.
        """
        for user_account in self.user_accounts.values():
            if user_account['username'] == username:
                return { "success": True, "data": user_account }
        return { "success": False, "error": "User account not found" }

    def get_participant_by_user_account(self, account_id: str = None, username: str = None) -> dict:
        """
        Given an account_id or username, retrieve the matching participant info.

        Args:
            account_id (str, optional): Account ID of the user.
            username (str, optional): Username of the user account.

        Returns:
            dict: {
                "success": True,
                "data": ParticipantInfo,
            }
            or
            {
                "success": False,
                "error": str,  # Reason for failure.
            }

        Constraints:
            - At least one identifier (account_id or username) must be provided.
            - The user account must exist and reference a valid participant.
        """
        # Need at least one identifier
        if not account_id and not username:
            return { "success": False, "error": "Must provide account_id or username." }

        # Find the user account
        user_account = None
        if account_id:
            user_account = self.user_accounts.get(account_id)
        elif username:
            # Search for username (assuming usernames are unique)
            user_account = next(
                (ua for ua in self.user_accounts.values() if ua["username"] == username),
                None
            )

        if not user_account:
            return { "success": False, "error": "User account not found." }

        participant_id = user_account.get("participant_id")
        participant_info = self.participants.get(participant_id)
        if not participant_info:
            return { "success": False, "error": "Participant not found for this user account." }

        return { "success": True, "data": participant_info }

    def get_participant_by_id(self, participant_id: str) -> dict:
        """
        Retrieve participant info using participant_id.

        Args:
            participant_id (str): The unique identifier for the participant.

        Returns:
            dict: {
                "success": True,
                "data": ParticipantInfo
            }
            or
            {
                "success": False,
                "error": str  # Reason why lookup failed.
            }

        Constraints:
            - The participant_id must exist in the system.
        """
        participant_info = self.participants.get(participant_id)
        if participant_info is None:
            return {
                "success": False,
                "error": "Participant with this ID does not exist."
            }

        return {
            "success": True,
            "data": participant_info
        }

    def list_enrollments_for_participant(self, participant_id: str) -> dict:
        """
        List all enrollment records for a given participant.

        Args:
            participant_id (str): Unique identifier of the participant.

        Returns:
            dict: {
                "success": True,
                "data": List[EnrollmentInfo],  # List of enrollment records for the participant (may be empty)
            }
            or
            {
                "success": False,
                "error": str  # Error message if participant does not exist
            }

        Constraints:
            - The participant_id must exist in the system.
            - All enrollment records for the given participant are returned.
        """
        if participant_id not in self.participants:
            return { "success": False, "error": "Participant not found" }

        result = [
            enrollment_info for enrollment_info in self.enrollments.values()
            if enrollment_info["participant_id"] == participant_id
        ]
        return { "success": True, "data": result }

    def list_current_enrollments_for_participant(self, participant_id: str) -> dict:
        """
        Lists all enrollment records for a participant where the enrollment_status is "enrolled".

        Args:
            participant_id (str): Unique identifier of the participant.

        Returns:
            dict: {
                "success": True,
                "data": List[EnrollmentInfo],  # List may be empty if no current enrollments
            }
            or
            {
                "success": False,
                "error": str  # If participant_id is invalid
            }

        Constraints:
            - The participant_id must exist in the system.
            - Only enrollments with enrollment_status "enrolled" are returned.
        """
        if participant_id not in self.participants:
            return { "success": False, "error": "Participant does not exist" }

        current_enrollments = [
            enrollment for enrollment in self.enrollments.values()
            if enrollment["participant_id"] == participant_id and enrollment["enrollment_status"] == "enrolled"
        ]

        return { "success": True, "data": current_enrollments }

    def get_clinical_trial_by_id(self, trial_id: str) -> dict:
        """
        Retrieve detailed information for a clinical trial given its trial_id.

        Args:
            trial_id (str): The unique ID for the clinical trial.

        Returns:
            dict: {
                "success": True,
                "data": ClinicalTrialInfo  # Information about the clinical trial
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure (e.g., not found)
            }

        Constraints:
            - trial_id must correspond to an existing clinical trial.
        """
        if not trial_id or trial_id not in self.clinical_trials:
            return { "success": False, "error": "Clinical trial not found" }
        return { "success": True, "data": self.clinical_trials[trial_id] }

    def list_clinical_trials_for_enrollments(self, enrollments: list) -> dict:
        """
        Given a list of enrollment records, fetch detailed trial information for each enrolled trial.

        Args:
            enrollments (list): List of EnrollmentInfo dicts.
                                Each should contain 'trial_id'.

        Returns:
            dict: {
                "success": True,
                "data": List[ClinicalTrialInfo]  # List containing trial info for each enrollment.
            }
            or
            {
                "success": False,
                "error": str  # Error message if input is invalid
            }

        Constraints:
            - Each enrollment must reference a valid clinical trial.
            - Invalid or missing trial references are ignored.
        """
        if not isinstance(enrollments, list):
            return { "success": False, "error": "Invalid input: enrollments must be a list of records." }

        result = []
        for enrollment in enrollments:
            if not isinstance(enrollment, dict):
                continue  # skip invalid enrollment format
            trial_id = enrollment.get('trial_id')
            if trial_id and trial_id in self.clinical_trials:
                result.append(self.clinical_trials[trial_id])
            # else skip enrollment (missing or invalid trial)

        return { "success": True, "data": result }

    def get_enrollment_status(self, enrollment_id: str) -> dict:
        """
        Retrieve the status of a specific enrollment.

        Args:
            enrollment_id (str): Unique identifier for the enrollment.

        Returns:
            dict: 
                On success:
                    {
                        "success": True,
                        "data": {
                            "enrollment_id": str,
                            "enrollment_status": str
                        }
                    }
                On failure:
                    {
                        "success": False,
                        "error": str  # Reason for failure, e.g. enrollment not found
                    }

        Constraints:
            - The enrollment_id must exist in the enrollments records.
        """
        enrollment = self.enrollments.get(enrollment_id)
        if not enrollment:
            return { "success": False, "error": "Enrollment record not found" }

        return {
            "success": True,
            "data": {
                "enrollment_id": enrollment_id,
                "enrollment_status": enrollment["enrollment_status"]
            }
        }

    def update_enrollment_status(self, enrollment_id: str, new_status: str, requesting_user_account_id: str = None) -> dict:
        """
        Change the status of a participant's enrollment.

        Args:
            enrollment_id (str): The unique ID of the enrollment to update.
            new_status (str): The new status value ('enrolled', 'withdrawn', or 'completed').
            requesting_user_account_id (str, optional): If supplied, only allow modification
                if this user owns the enrollment (access control).

        Returns:
            dict:
                On success:
                    { "success": True, "message": "Enrollment status updated successfully." }
                On failure:
                    { "success": False, "error": <reason> }

        Constraints:
            - enrollment_id must exist and reference valid participant and clinical trial.
            - new_status must be one of: "enrolled", "withdrawn", "completed".
            - If requesting_user_account_id is provided, only allow change if user owns the enrollment.
        """

        allowed_statuses = {"enrolled", "withdrawn", "completed"}

        enrollment = self.enrollments.get(enrollment_id)
        if enrollment is None:
            return { "success": False, "error": "Enrollment ID not found." }

        if new_status not in allowed_statuses:
            return { "success": False, "error": f"Invalid enrollment status: '{new_status}'." }

        # Check that enrollment references valid participant and clinical trial
        participant_id = enrollment.get("participant_id")
        trial_id = enrollment.get("trial_id")
        if participant_id not in self.participants:
            return { "success": False, "error": "Enrollment references invalid participant." }
        if trial_id not in self.clinical_trials:
            return { "success": False, "error": "Enrollment references invalid clinical trial." }

        # Optional: Check if requesting user has access/owns this enrollment
        if requesting_user_account_id is not None:
            user = self.user_accounts.get(requesting_user_account_id)
            if user is None:
                return { "success": False, "error": "Requesting user account not found." }
            if user.get("participant_id") != participant_id:
                return { "success": False, "error": "Permission denied: you may only modify your own enrollments." }

        # Perform update
        enrollment["enrollment_status"] = new_status
        return { "success": True, "message": "Enrollment status updated successfully." }

    def enroll_participant_in_trial(
        self,
        participant_id: str,
        trial_id: str,
        enrollment_date: str = None
    ) -> dict:
        """
        Create a new enrollment for a participant in a clinical trial, if consent_status is valid.

        Args:
            participant_id (str): ID of the participant to enroll.
            trial_id (str): ID of the clinical trial to enroll into.
            enrollment_date (str, optional): Date of enrollment (if not provided, uses today).

        Returns:
            dict: {
                "success": True,
                "message": "Participant enrolled in trial.",
                "enrollment_id": str  # The new enrollment's ID
            }
            or
            {
                "success": False,
                "error": str  # Explanation of failure (missing participant, invalid consent, etc.)
            }

        Constraints:
            - Only participants with valid consent_status ("valid") may be enrolled.
            - Each enrollment must reference valid participant and clinical trial.
            - Enrollment_status = "enrolled" at creation.
        """

        # Participant must exist
        participant = self.participants.get(participant_id)
        if not participant:
            return { "success": False, "error": "Participant not found." }

        # Trial must exist
        trial = self.clinical_trials.get(trial_id)
        if not trial:
            return { "success": False, "error": "Clinical trial not found." }

        # Consent must be valid
        valid_consent_statuses = {"valid", "active", "approved"}  # Assume these are valid
        if participant.get("consent_status", "").lower() not in valid_consent_statuses:
            return { "success": False, "error": "Participant's consent status is invalid." }

        # Set enrollment_date
        if enrollment_date is None:
            enrollment_date = datetime.utcnow().strftime("%Y-%m-%d")

        # Generate new unique enrollment_id
        enrollment_id = str(uuid.uuid4())

        # Create enrollment record
        enrollment_info = {
            "enrollment_id": enrollment_id,
            "participant_id": participant_id,
            "trial_id": trial_id,
            "enrollment_date": enrollment_date,
            "enrollment_status": "enrolled"
        }

        self.enrollments[enrollment_id] = enrollment_info

        return {
            "success": True,
            "message": "Participant enrolled in trial.",
            "enrollment_id": enrollment_id
        }

    def update_participant_consent_status(self, participant_id: str, new_consent_status: str) -> dict:
        """
        Change a participant's consent status (e.g., revoking or granting consent).

        Args:
            participant_id (str): The participant to be updated.
            new_consent_status (str): The updated consent status (should be a non-empty string).

        Returns:
            dict: {
                "success": True,
                "message": "Consent status for participant <participant_id> updated to <new_consent_status>."
            }
            or
            {
                "success": False,
                "error": str  # Error description
            }

        Constraints:
            - The participant must exist.
            - new_consent_status should be a non-empty string (more restrictions can be added if system supported values are enumerated).
        """
        if participant_id not in self.participants:
            return { "success": False, "error": f"Participant {participant_id} does not exist." }
        if not isinstance(new_consent_status, str) or not new_consent_status.strip():
            return { "success": False, "error": "Invalid consent status value." }

        self.participants[participant_id]["consent_status"] = new_consent_status.strip()
        return {
            "success": True,
            "message": f"Consent status for participant {participant_id} updated to {new_consent_status.strip()}."
        }

    def withdraw_participant_from_trial(self, participant_id: str, trial_id: str) -> dict:
        """
        Mark an enrollment record as "withdrawn" for the specified participant and clinical trial.

        Args:
            participant_id (str): The participant's unique identifier.
            trial_id (str): The clinical trial's unique identifier.

        Returns:
            dict: {
                "success": True,
                "message": "Participant has been marked as withdrawn from the trial."
            }
            or
            {
                "success": False,
                "error": <str>  # Reason for failure.
            }

        Constraints:
            - Enrollment must exist for the specified participant and trial.
            - Enrollment must reference valid participant/trial.
            - Withdrawal possible only if not already withdrawn/completed.
            - Status must be set to "withdrawn".
        """
        # Verify participant exists
        if participant_id not in self.participants:
            return { "success": False, "error": "Participant does not exist." }

        # Verify trial exists
        if trial_id not in self.clinical_trials:
            return { "success": False, "error": "Clinical trial does not exist." }

        # Find enrollment
        enrollment_to_update = None
        for enrollment in self.enrollments.values():
            if (enrollment["participant_id"] == participant_id and
                enrollment["trial_id"] == trial_id):
                enrollment_to_update = enrollment
                break

        if not enrollment_to_update:
            return { "success": False, "error": "Enrollment not found for participant in the specified trial." }

        # Check enrollment status
        current_status = enrollment_to_update["enrollment_status"].lower()
        if current_status == "withdrawn":
            return { "success": False, "error": "Participant is already withdrawn from this trial." }
        if current_status == "completed":
            return { "success": False, "error": "Cannot withdraw: enrollment is already completed." }

        # Update status
        enrollment_to_update["enrollment_status"] = "withdrawn"
        return {
            "success": True,
            "message": "Participant has been marked as withdrawn from the trial."
        }


    def create_user_account(
        self,
        username: str,
        hashed_password: str,
        participant_id: str,
        account_status: str
    ) -> dict:
        """
        Register a new user account linked to a participant profile.

        Args:
            username (str): Desired username for login.
            hashed_password (str): Securely hashed password string.
            participant_id (str): ID of participant to link this account to.
            account_status (str): Initial account status (e.g., 'active', 'pending', etc.).

        Returns:
            dict: 
                - On success: {
                      "success": True, 
                      "message": "User account created",
                      "account_id": str
                  }
                - On failure: {
                      "success": False,
                      "error": str
                  }

        Constraints:
            - Username must be unique among all user accounts.
            - Participant_id must exist in participants.
            - Each participant can be linked to only one user account.
        """
        # Username validity
        if not username:
            return { "success": False, "error": "Username cannot be empty" }
        # Check username uniqueness
        for account in self.user_accounts.values():
            if account["username"] == username:
                return { "success": False, "error": "Username already exists" }
        # Check participant_id exists
        if participant_id not in self.participants:
            return { "success": False, "error": "Participant does not exist" }
        # Check for existing account for participant
        for account in self.user_accounts.values():
            if account["participant_id"] == participant_id:
                return { "success": False, "error": "Participant already has an associated user account" }
        # Optionally check account_status
        if not account_status:
            return { "success": False, "error": "Account status cannot be empty" }
        # Generate a unique account ID
        account_id = str(uuid.uuid4())
        # Create new account
        user_account_info = {
            "account_id": account_id,
            "participant_id": participant_id,
            "username": username,
            "hashed_password": hashed_password,
            "account_status": account_status
        }
        self.user_accounts[account_id] = user_account_info
        return { "success": True, "message": "User account created", "account_id": account_id }

    def delete_enrollment(self, enrollment_id: str) -> dict:
        """
        Remove an enrollment record by its enrollment ID (admin action).

        Args:
            enrollment_id (str): The ID of the enrollment to be deleted.

        Returns:
            dict: {
                "success": True,
                "message": "Enrollment <enrollment_id> deleted successfully."
            }
            or
            {
                "success": False,
                "error": <error message>
            }

        Constraints:
            - The enrollment must exist before deletion.
            - (Referential integrity: Enrollment is a link; no further cleanup required.)
        """
        if enrollment_id not in self.enrollments:
            return {
                "success": False,
                "error": f"Enrollment ID '{enrollment_id}' does not exist."
            }

        del self.enrollments[enrollment_id]
        return {
            "success": True,
            "message": f"Enrollment '{enrollment_id}' deleted successfully."
        }

    def update_clinical_trial_status(self, trial_id: str, new_status: str) -> dict:
        """
        Change the status of a clinical trial (e.g., 'active', 'completed', 'suspended').

        Args:
            trial_id (str): The unique identifier of the clinical trial to update.
            new_status (str): The new status to set for the clinical trial.

        Returns:
            dict: On success:
                { "success": True, "message": "Clinical trial status updated to <new_status>." }
            On error:
                { "success": False, "error": "<reason>" }

        Constraints:
            - trial_id must reference an existing clinical trial.
            - new_status must be one of allowed status values: ["active", "completed", "suspended"]
        """
        allowed_statuses = ["active", "completed", "suspended"]
        if trial_id not in self.clinical_trials:
            return {"success": False, "error": "Clinical trial not found."}
        if new_status not in allowed_statuses:
            return {"success": False, "error": f"Invalid status: {new_status}. Allowed: {allowed_statuses}"}

        self.clinical_trials[trial_id]["status"] = new_status
        return {"success": True, "message": f"Clinical trial status updated to '{new_status}'."}

